LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
 
ARCHITECTURE fsm OF Control IS

   -- Architecture Declarations
   Constant NOUGHTS : std_logic_vector := "0000000000"; 

   TYPE STATE_TYPE IS (
      flush,
      getkey,
      load_u,
      load_t,
      standby,
      alarm,
      counting,
      suspended,
      end_count
   );
 
   -- Declare current and next state signals
   SIGNAL current_state : STATE_TYPE;
   SIGNAL next_state : STATE_TYPE;
   -- pragma synthesis_off
   SIGNAL hds_next,hds_current,hds_clock: INTEGER;
   -- pragma synthesis_on

   -- Declare any pre-registered internal signals
   SIGNAL beep_int : std_logic ;

BEGIN

   -----------------------------------------------------------------
   clocked_proc : PROCESS ( 
      clk,
      reset
   )
   -----------------------------------------------------------------
   BEGIN
      IF (reset = '1') THEN
         current_state <= flush;
         -- Default Reset Values
         beep <= '0';
         -- pragma synthesis_off
         hds_current <= 0;
         -- pragma synthesis_on
      ELSIF (clk'EVENT AND clk = '0') THEN
         current_state <= next_state;
         -- pragma synthesis_off
         hds_current <= hds_next;
         hds_clock <= -1;
         hds_clock <= 0;
         -- pragma synthesis_on
         -- Registered output assignments
         beep <= beep_int;
      END IF;
   END PROCESS clocked_proc;
 
   -----------------------------------------------------------------
   nextstate_proc : PROCESS ( 
      current_state,
      d,
      start,
      stop,
      zero
   )
   -----------------------------------------------------------------
   BEGIN
      CASE current_state IS
         WHEN flush => 
            IF (d /= NOUGHTS) THEN 
               next_state <= load_u;
               -- pragma synthesis_off
               hds_next <= 1;
               -- pragma synthesis_on
            ELSE
               next_state <= flush;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN getkey => 
            IF (start = '1') THEN 
               next_state <= standby;
               -- pragma synthesis_off
               hds_next <= 2;
               -- pragma synthesis_on
            ELSIF (stop='1') THEN 
               next_state <= flush;
               -- pragma synthesis_off
               hds_next <= 3;
               -- pragma synthesis_on
            ELSIF (d /= NOUGHTS) THEN 
               next_state <= load_u;
               -- pragma synthesis_off
               hds_next <= 4;
               -- pragma synthesis_on
            ELSE
               next_state <= getkey;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN load_u => 
            next_state <= load_t;
            -- pragma synthesis_off
            hds_next <= 5;
            -- pragma synthesis_on
         WHEN load_t => 
            IF (d /= NOUGHTS) THEN 
               next_state <= getkey;
               -- pragma synthesis_off
               hds_next <= 6;
               -- pragma synthesis_on
            ELSE
               next_state <= load_t;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN standby => 
            IF (zero = '1') THEN 
               next_state <= alarm;
               -- pragma synthesis_off
               hds_next <= 7;
               -- pragma synthesis_on
            ELSIF (start = '1') THEN 
               next_state <= counting;
               -- pragma synthesis_off
               hds_next <= 8;
               -- pragma synthesis_on
            ELSE
               next_state <= standby;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN alarm => 
            IF (stop = '1') THEN 
               next_state <= end_count;
               -- pragma synthesis_off
               hds_next <= 9;
               -- pragma synthesis_on
            ELSE
               next_state <= alarm;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN counting => 
            IF (zero = '1') THEN 
               next_state <= alarm;
               -- pragma synthesis_off
               hds_next <= 10;
               -- pragma synthesis_on
            ELSIF (stop = '1') THEN 
               next_state <= suspended;
               -- pragma synthesis_off
               hds_next <= 11;
               -- pragma synthesis_on
            ELSE
               next_state <= counting;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN suspended => 
            IF (stop = '0') THEN 
               next_state <= counting;
               -- pragma synthesis_off
               hds_next <= 12;
               -- pragma synthesis_on
            ELSE
               next_state <= suspended;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN end_count => 
            IF (stop='1') THEN 
               next_state <= flush;
               -- pragma synthesis_off
               hds_next <= 13;
               -- pragma synthesis_on
            ELSE
               next_state <= end_count;
               -- pragma synthesis_off
               hds_next <= 0;
               -- pragma synthesis_on
            END IF;
         WHEN OTHERS =>
            next_state <= flush;
            -- pragma synthesis_off
            hds_next <= 0;
            -- pragma synthesis_on
      END CASE;
   END PROCESS nextstate_proc;
 
   -----------------------------------------------------------------
   output_proc : PROCESS ( 
      current_state
   )
   -----------------------------------------------------------------
   BEGIN

      -- Combined Actions
      CASE current_state IS
         WHEN flush => 
            hold <= '1';
            clear <= '1' ;
            beep <= '0' ;
         WHEN getkey => 
            hold <= '1' ;
         WHEN load_u => 
            hold <= '1' ;
            load <= '1' ;
         WHEN load_t => 
            hold <= '1' ;
         WHEN standby => 
            hold <= '1' ;
         WHEN alarm => 
            hold <= '1' ;
            clear <= '1' ;
            beep <= '1' ;
         WHEN suspended => 
            hold <= '1' ;
         WHEN end_count => 
            hold <= '1' ;
            clear <= '1' ;
         WHEN OTHERS =>
            NULL;
      END CASE;
   END PROCESS output_proc;
 
END fsm;
